import React, { useCallback, useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";
import { Modal } from "antd";

export default function VehiclesFormModal({
  ismodalOpen,
  setisModalOpen,
  vehicle,
  modalTitle = "Add new vehicle",
  updated,
  setUpdated,
}) {
  console.log("vehicle at modal", vehicle);
  console.log("isModalOpen", ismodalOpen);

  const [crew, setCrew] = useState(
    vehicle && vehicle.crew_array
      ? vehicle.crew_array.map((i) => ({ label: i.title, value: i.id }))
      : []
  );

  const getSaccoPersonnelActionsApi = useApi(transportApi.transportAction);
  const getSaccoPersonnel = async () => {
    await getSaccoPersonnelActionsApi.request({
      action: "GetSaccoPersonnel",
    });
  };

  useEffect(() => {
    getSaccoPersonnel();
  }, []);

  useEffect(() => {
    if (
      getSaccoPersonnelActionsApi.data &&
      getSaccoPersonnelActionsApi.data.length
    ) {
      setCrew(
        getSaccoPersonnelActionsApi.data.map((i) => ({
          label: `${i.first_name} ${i.first_name} - ${i.phone}`,
          value: i.id,
        }))
      );
    }

    console.log(
      "getSaccoPersonnelActionsApi.data",
      getSaccoPersonnelActionsApi.data
    );
  }, [getSaccoPersonnelActionsApi.data]);

  const [routes, setRoutes] = useState([]);
  const getRoutesActionsApi = useApi(transportApi.transportAction);
  const transportActionsApi = useApi(transportApi.transportAction);
  const getRoutes = async () => {
    await getRoutesActionsApi.request({
      action: "GetEntityRoutes",
    });
  };

  useEffect(() => {
    getRoutes();
  }, []);

  useEffect(() => {
    if (getRoutesActionsApi.data && getRoutesActionsApi.data.length) {
      setRoutes(
        getRoutesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("getRoutesActionsApi.data", getRoutesActionsApi.data);
  }, [getRoutesActionsApi.data]);

  const [errors, setErrors] = useState();

  const handleVehicleAction = async (data) => {
    console.log("data at", data);
    const result = await transportActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {}, [vehicle]);

  useEffect(() => {
    if (transportActionsApi.data) {
      // setisModalOpen(false);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (transportActionsApi.data.errors) {
        setErrors(transportActionsApi.data.errors);
      }
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  const saccoSubscritionActionsApi = useApi(transportApi.transportAction);

  const [saccoSubscriptions, setsaccoSubscriptions] = useState([]);
  const getSaccoSubscriptions = useCallback(async () => {
    await saccoSubscritionActionsApi.request({
      action: "GetSaccoSubscriptions",
    });
  }, []);

  useEffect(() => {
    if (
      saccoSubscritionActionsApi.data &&
      saccoSubscritionActionsApi.data.length
    ) {
      setsaccoSubscriptions(
        saccoSubscritionActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    if (
      saccoSubscritionActionsApi.data &&
      saccoSubscritionActionsApi.data.response_message &&
      saccoSubscritionActionsApi.data.response_code === 1
    ) {
      toast.error(saccoSubscritionActionsApi.data.response_message);
    }

    if (
      saccoSubscritionActionsApi.data &&
      saccoSubscritionActionsApi.data.response_message &&
      saccoSubscritionActionsApi.data.response_code === 0
    ) {
      toast.success(saccoSubscritionActionsApi.data.response_message);
    }

    console.log(
      "saccoSubscritionActionsApi.data",
      saccoSubscritionActionsApi.data
    );
  }, [saccoSubscritionActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    getSaccoSubscriptions();
  }, []);

  const formik = useFormik({
    initialValues: {
      administrator: vehicle
        ? { label: vehicle.administrator_title, value: vehicle.administrator }
        : "",
      conductor: vehicle
        ? { label: vehicle.conductor_title, value: vehicle.conductor }
        : "",
      driver: vehicle
        ? { label: vehicle.driver_title, value: vehicle.driver }
        : "",
      title: vehicle ? vehicle.title : "",
      is_active: vehicle ? vehicle.is_active : "",
      seats: vehicle ? vehicle.seats : "",
      registration: vehicle ? vehicle.registration : "",
      crew_members:
        vehicle && vehicle.crew_members
          ? vehicle.crew_members.map((i) => ({
              label: `${i.first_name} ${i.last_name} - ${i.identifier_number}`,
              value: i.id,
            }))
          : [],
      routes:
        vehicle && vehicle.routes
          ? vehicle.routes.map((i) => ({ label: i.title, value: i.id }))
          : [],
      sacco_subscriptions:
        vehicle && vehicle.sacco_subscriptions
          ? vehicle.sacco_subscriptions.map((i) => ({
              label: i.title,
              value: i.id,
            }))
          : [],
    },

    validationSchema: Yup.object({
      registration: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Vehicle plate number is required"),
      routes: Yup.array()
        .min(2, "Add at least two routes (from and to)")
        .label("Routes"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      let crewArr = [];
      if (values.crew_members && values.crew_members.length) {
        values.crew_members.map((x) => {
          crewArr.push(x.value);
        });
      }

      let routesArr = [];
      if (values.routes && values.routes.length) {
        values.routes.map((x) => {
          routesArr.push(x.value);
        });
      }

      let saccoSubscriptionsArr = [];
      if (values.sacco_subscriptions && values.sacco_subscriptions.length) {
        values.sacco_subscriptions.map((x) => {
          saccoSubscriptionsArr.push(x.value);
        });
      }

      console.log("subsc", saccoSubscriptionsArr);

      if (vehicle) {
        handleVehicleAction({
          action: "UpdateVehicle",
          vehicle_details: {
            vehicle_id: vehicle.id,
            title: values.title,
            seats: values.seats,
            registration: values.registration ? values.registration : "",
            routes: routesArr,
            administrator_id: values.administrator.value,
            driver_id: values.driver.value,
            conductor_id: values.conductor.value,
            sacco_subscriptions: saccoSubscriptionsArr,
            is_active: values.is_active,
          },
        });
      } else {
        handleVehicleAction({
          action: "CreateVehicle",
          vehicle_details: {
            title: values.title,
            seats: values.seats,
            registration: values.registration ? values.registration : "",
            administrator_id: values.administrator.value,
            driver_id: values.driver.value,
            conductor_id: values.conductor.value,
            routes: routesArr,
            sacco_subscriptions: saccoSubscriptionsArr,
            is_active: values.is_active,
          },
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    console.log("Swict", checked);
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");

    // console.log('eee', e.target.checked)
  };

  return (
    <div className="w-full">
      <Modal
        width={720}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.registration}
            error={formik.errors.registration}
          >
            <CustomInput
              required={true}
              id="registration"
              name="registration"
              onChange={formik.handleChange}
              placeholder="Enter vehicle plate number"
              size="large"
              type="text"
              value={formik.values.registration}
              label="Registration number"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter vehicle name or nickname"
              size="large"
              type="text"
              value={formik.values.title}
              label="name or nickname"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.seats}
            error={formik.errors.seats}
          >
            <CustomInput
              required={true}
              id="seats"
              name="seats"
              onChange={formik.handleChange}
              placeholder="Enter number of seats"
              size="large"
              type="number"
              value={formik.values.seats}
              label="Number of seats"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.routes}
            error={formik.errors.routes}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="routes"
              id="routes"
              label="Select routes"
              size="large"
              onChange={(value) => formik.setFieldValue("routes", value)}
              value={formik.values.routes}
              placeholder="Select routes"
              options={routes}
              isMulti={true}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.administrator}
            error={formik.errors.administrator}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="administrator"
              id="administrator"
              label="Add administrator members"
              size="large"
              onChange={(value) => formik.setFieldValue("administrator", value)}
              value={formik.values.administrator}
              placeholder="Select administrator"
              options={crew}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.driver}
            error={formik.errors.driver}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="driver"
              id="driver"
              label="Add driver "
              size="large"
              onChange={(value) => formik.setFieldValue("driver", value)}
              value={formik.values.driver}
              placeholder="Select driver"
              options={crew}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.conductor}
            error={formik.errors.conductor}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="conductor"
              id="conductor"
              label="Add conductor"
              size="large"
              onChange={(value) => formik.setFieldValue("conductor", value)}
              value={formik.values.conductor}
              placeholder="Select conductor"
              options={crew}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.sacco_subscriptions}
            error={formik.errors.sacco_subscriptions}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="sacco_subscriptions"
              id="sacco_subscriptions"
              label="Add sacco_subscriptions members"
              size="large"
              onChange={(value) =>
                formik.setFieldValue("sacco_subscriptions", value)
              }
              value={formik.values.sacco_subscriptions}
              placeholder="Select sacco subscriptions"
              options={saccoSubscriptions}
              isMulti={true}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
              checkedChildren="Deactivate"
              unCheckedChildren="Activate"
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
