import React, { useEffect, useRef, useState } from "react";
import VehiclesTable from "./VehiclesTable";

import useApi from "../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import transportApi from "../../../api/transport/transportApi";
import { ToastContainer, toast } from "react-toastify";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import VehiclesFormModal from "./VehiclesFormModal";

const columns = [
  { name: "Registration", uid: "registration" },
  { name: "Title", uid: "title" },
  { name: "Seats", uid: "seats" },
  { name: "Active", uid: "is_active" },
  { name: "Account Number", uid: "collection_account_number" },
  { name: "Administrator", uid: "administrator_title" },
  { name: "Date Added", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function VehiclesList() {
  const [ismodalOpen, setisModalOpen] = useState(false);

  const navigate = useNavigate();
  const [vehicle, setVehicle] = useState();
  const [vehicles, setVehicles] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");

  const transportActionsApi = useApi(transportApi.transportAction);

  const getVehicles = async () => {
    await transportActionsApi.request({
      action: "GetEntityVehicles",
    });
  };

  useEffect(() => {
    getVehicles();
  }, []);

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.length) {
      setVehicles(transportActionsApi.data);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 1
    ) {
      toast.error(transportActionsApi.data.response_message);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 0
    ) {
      toast.success(transportActionsApi.data.response_message);
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    setdata(vehicles);
  }, [vehicles]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      vehicles &&
      vehicles.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        vehicles.filter((x) =>
          x.registration.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(vehicles);
    }
  };

  useEffect(() => {
    getVehicles();
  }, [updated]);

  const handleEditAction = (item) => {
    setisModalOpen(true);
    setVehicle(item);
    setmodalTitle(`EDIT ${item.registration}`);
    setUpdated(false);
  };

  const handleAddAction = () => {
    setisModalOpen(true);
    setmodalTitle("Add new vehicle");
    setVehicle(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/transport/vehicles/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/routes/delete/${item.id}`);
  };

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.length) {
      setVehicles(transportActionsApi.data);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 1
    ) {
      toast.error(transportActionsApi.data.response_message);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 0
    ) {
      toast.success(transportActionsApi.data.response_message);
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    getVehicles();
  }, [updated]);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
    
      getVehicles();

    
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 30 seconds
      timerIdRef.current = setInterval(pollingCallback, 30000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled, getVehicles]);

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />
      {ismodalOpen && (
        <VehiclesFormModal
          ismodalOpen={ismodalOpen}
          setisModalOpen={setisModalOpen}
          vehicle={vehicle}
          modalTitle={modalTitle}
          updated={updated}
          setUpdated={setUpdated}
        />
      )}
      <VehiclesTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default VehiclesList;
